package dev.pedro.learning.ecommerce.payment;import dev.pedro.learning.ecommerce.payment.provider.*;import io.quarkus.test.junit.QuarkusTest;import jakarta.inject.Inject;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;@QuarkusTest class PaymentCircuitBreakerTest{@Inject FakePaymentProviderState provider;@Inject PaymentProviderGateway gateway;@Test void repeatedFailuresEventuallyFailFast(){provider.reset();gateway.resetStats();provider.configureMode(PaymentProviderMode.ALWAYS_FAIL);for(int i=0;i<20;i++){ProviderPaymentResponse response=gateway.pay(new ProviderPaymentRequest(UUID.randomUUID(),new BigDecimal("10.00"),"test-"+i));assertFalse(response.success());}assertTrue(gateway.fallbackCount()>0);assertTrue(provider.calls()<20,"Once open, some gateway calls should not contact the provider");}}